def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = OrderedDict()
        lock = threading.RLock()

        def wrapped(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            with lock:
                try:
                    value, created = cache[key]
                    if created or time.monotonic() - created < ttl:
                        return value
                except KeyError:
                    pass
                result = func(*args, **kwargs)
                if maxsize == 0 or len(cache) < maxsize:
                    cache[key] = result, timer()
                else:
                    first_item = next(iter(cache))
                    del cache[first_item]
                    cache[key] = result, timer()
                return result
        return wrapped
    return wrapper

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    cache = OrderedDict()

    def decorator(func):
        nonlocal cache

        @wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = (args, frozenset(kwargs.items()))
            else:
                key = (args, frozenset(kwargs.items()))

            if key not in cache:
                cache[key] = func(*args, **kwargs)
                if len(cache) > maxsize:
                    cache.popitem(last=False)

            return cache[key]

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = dict()
        recent_keys = deque()
        def wrapper(*args):
            key = args if typed else tuple(args)
            if key in cache:
                recent_keys.remove(key)
                recent_keys.append(key)
                return cache[key]
            else:
                result = func(*args)
                cache[key] = result
                recent_keys.append(key)
                if len(cache) > maxsize:
                    oldest_key = recent_keys.popleft()
                    del cache[oldest_key]
                return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    # Decorator to wrap a function with a memoizing callable that saves
    # up to `maxsize` results based on a Least Frequently Used (LFU)
    # algorithm.
    def wrapper(func):
        cache = {}
        maximumCacheSize = maxsize

        def decoratedFunction(*args):
            # Call the inner function and add it to the cache if we
            # haven't reached the maximum cache size.
            key = (args, tuple(typed))
            if not key in cache:
                cache[key] = func(*args)
            else:
                cache[key] = cache[key * (cache[key] + 1)]

        return decoratedFunction

    return wrapper

def popitem(self):
    if len(self) == 0:
        raise KeyError("The container is empty")
    elif len(self) == 1:
        return self.pop()
    else:
        item = next(iter(self))
        value = self[item]
        self.pop(item)
        return item, value

