def extostr(cls, e, max_level=30, max_path_level=5):
    out = "Exception '{0}': {1}\n".format(type(e).__name__, str(e))
    traceback = traceback.extract_tb(e.__traceback__, max_level)
    for item in traceback:
        if len(out) > max_path_level:
            break
        file_name, line_number, function_name, text = item
        out += "  {0}: {1} in {2}()\n".format(file_name, line_number, function_name)
    return out
