def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent

    Arguments:
        classes (list): List of base classes

    Returns:
        list: Minimal base classes
    """
    base_classes = {}

    for cls in classes:
        cls_split = cls.split('.')

        # Check if parent class exists
        if not base_classes.get(cls_split[2]):
            base_classes[cls_split[2]] = {}

        # Check if child class exists
        base_classes[cls_split[2]][cls] = {}


    return base_classes

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface.

    Parameters:
        all (bool): Whether to include non-editable attributes or not.

    Yields:
        tuple: Tuple of attribute name and description.
    """
    for attrib_name, attrib in self.interface.attributes.items():
        if all or attrib.editable:
            yield attrib_name, attrib.description

