    """.. deprecated:: 0.5 in Lena 0.5, to_csv is not used.
            Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    def __init__(self, separator=",", header=None):
        self.separator = separator
        self.header = header

    def __call__(self, graph):
        # deprecated, replaced by ./lena/output.py:ToCSV
        raise NotImplementedError("This method is deprecated,  to_csv is not used. "
                                  "Iterables are converted to tables.")

        # if graph.ndim == 1:
        #     return graph

        if graph.points is not None:
            points = graph.points
        else:
            points = graph.copy

        if points.ndim == 1:
            if self.separator == "":
                csv = "\n".join([",".join(map(str, row)) for row in points])
            else:
                csv = "\n".join([self.separator.join(map(str, row)) for row in points])
            if self.header is not None:
                csv = self.header + "\n" + csv
            return csv

        elif points.ndim == 2:
            headers = ["x{}".format(i) for i in range(points.shape[1])]
            headers += ["y{}".format(i) for i in range(points.shape[1])]
            csv = ""
            for row in points:
                csv += self.separator.join([str(cell) for cell in row]) + "\n"

            if self.header is not None:
               csv = self.header + "\n" + csv
            return csv

        else:
            return "\n-----\nUnknown ndim {}, graph points have ndim 1 or 2\n-----\n".format(points.ndim)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    for i, e in enumerate(seq):
        if type(e) == FillRequest:
            return True
        elif type(e) == list and not is_source_seq(e):
            if is_fill_request_seq(e):
                return True
    return False

