def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generates part of a default ``observer_schema`` recursively from part of a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = []
            for item in value:
                if isinstance(item, dict):
                    observer_schema[key].append(generate_default_observer_schema_dict(item))
                else:
                    observer_schema[key].append(None)
        else:
            observer_schema[key] = None

    if first_level:
        id_keys = ["name", "namespace", "kind", "uid"]
        for key in id_keys:
            if key in manifest_dict:
                observer_schema[key] = manifest_dict[key]

    return observer_schema

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Update a partial last_applied_manifest from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): Partial last_applied_manifest being updated.
        observer_schema (dict): Partial observer_schema.
        response (dict): Partial Kubernetes response.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response.

    This function iterates through all observed fields in the observer_schema and initializes their value in the last_applied_manifest if they are not yet present.
    """
    for field in observer_schema["observed_fields"]:
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response.")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
    for child in observer_schema.get("child_types", []):
        if child["name"] in response:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(child["name"], {}), child, response[child["name"]])

