def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Validate OCFL object at path or pyfs root
    if isinstance(path, str):
        if path.startswith('/.well-known/ocfl/') or path == '/':
            pass

    else:
        if path.isdir() and path.abspath().startswith(path.pyd.root):
            pass

    # Raise exception if OCFL object is invalid
    raise ValidationError(f'Invalid OCFL object at path {path}.')

    # Validate OCFL object directory structure
    if not path.exists():
        raise FileNotFoundError(f'Could not find file or directory at path {path}.')

    if not path.isdir():
        raise NotADirectoryError(f'Path {path} is not a directory.')

    if not path.join('.well-known/ocfl').exists():
        raise FileNotFoundError(f'Could not find .well-known/ocfl directory at path {path}.')

    if not path.join('.well-known/ocfl', 'extension').exists():
        raise FileNotFoundError(f'Could not find .well-known/ocfl/extension file at path {path}.')

    if not path.join('.well-known/ocfl', 'top-level.json').exists():
        raise FileNotFoundError(f'Could not find .well-known/ocfl/top-level.json file at path {path}.')

    if not path.join('.well-known/ocfl', 'extension', 'ocfl_1.0.json').exists():
        raise FileNotFoundError(f'Could not find .well-known/ocfl/extension/ocfl_1.0.json file at path {path}.')

    if not path.join('ocfl_object').exists():
        raise FileNotFoundError(f'Could not find ocfl_object directory at path {path}.')

    if not path.join('ocfl_object', 'head').exists():
        raise FileNotFoundError(f'Could not find ocfl_object/head directory at path {path}.')

    if not path.join('ocfl_object', 'versions').exists():
        raise FileNotFoundError(f'Could not find ocfl_object/versions directory at path {path}.')

    if not path.join('ocfl_object', 'content').exists():
        raise FileNotFoundError(f'Could not find ocfl_object/content directory at path {path}.')

    if not path.join('ocfl_object', 'inventory.json').exists():
        raise FileNotFoundError(f'Could not find ocfl_object/inventory.json file at path {path}.')

    # Validate OCFL object inventory
    with open(path.join('ocfl_object', 'inventory.json'), 'r') as f:
        try:
            data = json.load(f)
            digests = []
            contents = []
            versions = data['versions']
            for version in versions:
                if version['bundledObject']['directoryPath'] == '':
                    continue
                contents.append(version['bundledObject']['directoryPath'])
                digestType = version['bundledObject']['digestType']
                digestValue = version['bundledObject']['digestValue']
                for content in contents:
                    if digestType == 'sha1':
                        digests.append((content, sha1(content).hexdigest()))
                    elif digestType == 'md5':
                        digests.append((content, md5(content).hexdigest()))
                    elif digestType == 'crc32':
                        digests.append((content, crc32(content).hexdigest()))
                    else:
                        raise ValueError(f'Invalid digest type: {digestType}.')
            for digest in data['digests']:
                for (content, expected_digest) in digests:
                    if digest['algorithm'] == expected_digest:
                        if digest['value'] == expected_digest:
                            break
                        else:
                            raise ValueError(f'Invalid digest value for {content}: {digest["value"]}.')
                    elif digest['algorithm'] == 'manual':
                        # Ignore manual digest
                        break
                    else:
                        raise ValueError(f'Invalid digest algorithm: {digest["algorithm"]}.')
            for content in contents:
                if not path.join('ocfl_object', 'versions', content).exists():
                    raise FileNotFoundError(f'Could not find {content} at path {path}/ocfl_object/versions.')
            return True
        except (ValueError, FileNotFoundError, TypeError) as e:
            raise ValidationError(e)

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix.

    Parameters:
        prefix (str): The prefix to add to the status string.

    Returns:
        str: The status string.
    """
    out = []
    for attr in self._validator_output:
        if self._validator_output[attr]:
            out.append(prefix + attr + ': ' + ", ".join(self._validator_output[attr]))
    return "\n".join(out)

