def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Raise ValueError if the inventory is not a dict or a list
    if not isinstance(inventory, (dict, list)):
        raise ValueError("Inventory must be a dict or a list")

    # Extract the spec version from the type value if needed
    if extract_spec_version:
        try:
            spec_version = inventory.pop("type").split("csaf-")[1]
        except (AttributeError, KeyError, IndexError):
            pass

    # Use the extracted spec version or the default spec version, then validate the inventory
    with suppress(AttributeError):
        validate_spec_version(spec_version or self.spec_version)
    return validate_inventory(inventory, schema_mapping[spec_version])

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used.

    Parameters:
        manifest_files (list[str]): The list of manifest files.
        digests_used (set[str]): The set of digest values that are used.
    """

    # Check that all required digests are present in the manifest
    for digest in self.digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is required but not present in the manifest.")

    # Check that all digests used are present in the manifest
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is used but not present in the manifest.")

    # Check that all digests in the manifest are used
    for manifest_file in manifest_files:
        if manifest_file not in digests_used:
            raise ValueError(f"Digest {manifest_file} is present in the manifest but not used.")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # check that prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    # check that self and prior inventories have the same schema version
    if self.schema_version != prior.schema_version:
        raise InconsistentInventoryError(f"Inventory schema version mismatch: current version is {self.schema_version}, prior version is {prior.schema_version}")

    # check that self and prior inventories have the same full set of products
    if set(self.products.keys()) != set(prior.products.keys()):
        raise InconsistentInventoryError(f"Product set mismatch: current inventory has {self.products.keys()}, prior inventory has {prior.products.keys()}")

    # check that for each product, the prior inventory has the same set of product attributes and values
    for product_id in self.products:
        prior_product = prior.products[product_id]
        if set(self.products[product_id].keys()) != set(prior_product.keys()) or set(self.products[product_id].values()) != set(prior_product.values()):
            raise InconsistentInventoryError(f"Product {product_id} attributes mismatch: current inventory has {self.products[product_id].items()}, prior inventory has {prior_product.items()}")

    # check that the current inventory has the same set of storage locations
    if set(self.storage_locations.keys()) != set(prior.storage_locations.keys()):
        raise InconsistentInventoryError(f"Storage location set mismatch: current inventory has {self.storage_locations.keys()}, prior inventory has {prior.storage_locations.keys()}")

    # check that for each storage location, the prior inventory has the same set of product assignments
    for location_id in self.storage_locations:
        prior_location = prior.storage_locations[location_id]
        if set(self.storage_locations[location_id].keys()) != set(prior_location.keys()):
            raise InconsistentInventoryError(f"Storage location {location_id} product assignment mismatch: current inventory has {self.storage_locations[location_id].items()}, prior inventory has {prior.storage_locations[location_id].items()}")

    # check that both inventories have the same set of labeling schema versions
    if set(self.labeling_schema_versions.keys()) != set(prior.labeling_schema_versions.keys()):
        raise InconsistentInventoryError(f"Labeling schema version set mismatch: current inventory has {self.labeling_schema_versions.keys()}, prior inventory has {prior.labeling_schema_versions.keys()}")

    # check that for each labeling schema version, the prior inventory has the same set of product labels
    for schema_version in self.labeling_schema_versions:
        prior_labels = prior.labeling_schema_versions[schema_version]
        if set(self.labeling_schema_versions[schema_version].keys()) != set(prior_labels.keys()):
            raise InconsistentInventoryError(f"Product label set mismatch for schema version {schema_version}: current inventory has {self.labeling_schema_versions[schema_version].keys()}, prior inventory has {prior.labeling_schema_versions[schema_version].keys()}")

    # check that for each labeling schema version, the prior inventory has the same set of label attributes and values
    for schema_version in self.labeling_schema_versions:
        for product_id in self.labeling_schema_versions[schema_version]:
            prior_labels = prior.labeling_schema_versions[schema_version][product_id]
            if set(self.labeling_schema_versions[schema_version][product_id].keys()) != set(prior_labels.keys() or set(prior_labels.values()):
                raise InconsistentInventoryError(f"Product {product_id} label set mismatch for schema version {schema_version}: current inventory has {self.labeling_schema_versions[schema_version][product_id].items()}, prior inventory has {prior.labeling_schema_versions[schema_version][product_id].items()}")

