def render(pieces, style):
    # Initialize an empty string to hold the rendered version
    rendered = ""

    # Iterate over the pieces and style, appending the rendered content to the string
    for piece, styled in itertools.zip_longest(pieces, style):
        # Determine the style to use for this piece
        if styled in ["italic", "italic_mono", "bold", "bold_mono"]:
            style = styled

        # Choose the right function to call based on the style
        if style == "italic":
            rendered += italics(piece)
        elif style == "italic_mono":
            rendered += monospaced_italics(piece)
        elif style == "bold":
            rendered += bold(piece)
        elif style == "bold_mono":
            rendered += monospaced_bold(piece)
        else:
            rendered += piece

    # Return the rendered string
    return rendered

