import ruamel

def deep_merge_nodes(nodes: list[(ScalarNode, MappingNode or Node)]) -> list[(ScalarNode, MappingNode or Node)]:
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (ScalarNode as a key, MappingNode or other Node as a value),

    ... deep merges any node values corresponding to duplicate keys and returns the result. If there are colliding keys with non-MappingNode values (e.g., integers or strings), the last of the values wins.

    For instance, given node values of:

        [
            (ScalarNode(tag='tag:yaml.org,2002:str', value='retention'), MappingNode(tag='tag:yaml.org,2002:map', value=[
                (ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'), ScalarNode(tag='tag:yaml.org,2002:int', value='24')),
                (ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'), ScalarNode(tag='tag:yaml.org,2002:int', value='7')),
            ])),
            (ScalarNode(tag='tag:yaml.org,2002:str', value='retention'), MappingNode(tag='tag:yaml.org,2002:map', value=[
                (ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'), ScalarNode(tag='tag:yaml.org,2002:int', value='5')),
            ])),
        ]

    ... the returned result would be:

        [
            (ScalarNode(tag='tag:yaml.org,2002:str', value='retention'), MappingNode(tag='tag:yaml.org,2002:map', value=[
                (ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'), ScalarNode(tag='tag:yaml.org,2002:int', value='24')),
                (ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'), ScalarNode(tag='tag:yaml.org,2002:int', value='5')),
            ]))]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    result = []
    key_to_node_value = collections.defaultdict(list)
    for node_value in nodes:
        key = node_value[0]
        node_value[1].tag = ruamel.yaml.comments.CommentedMap
        key_to_node_value[key].append(node_value[1])
    for key in key_to_node_value:
        result.append((key, _merge_node_values(key_to_node_value[key])))
    return result

def _merge_node_values(node_values: list[MappingNode or Node]) -> MappingNode or Node:
    """
    Given a sequence of one or more node values corresponding to a key in a nested
    borgmatic configuration data structure, deep merge the values, which can be nodes or
    lists of nodes, as appropriate. If there are colliding keys with non-MappingNode values
    (e.g., integers or strings), the last of the values wins.
    """
    if len(node_values) == 1:
        return node_values[0]

    result = None
    for node_value in node_values:
        if result is None:
            result = node_value
            continue

        if isinstance(node_value, MappingNode):
            if isinstance(result, MappingNode):
                for key in node_value:
                    if key in result:
                        result[key] = _merge_node_values([result[key], node_value[key]])
                    else:
                        result[key] = node_value[key]
            else:
                result = node_value
        else:
            if isinstance(result, MappingNode):
                result = _merge_node_values([result, node_value])
            else:
                result = node_value

    return result

