def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parser_results = {}
    remaining_args = []

    # gin up a parser to use for all subparsers to eat common arguments
    # like --repository
    common_args_parser = argparse.ArgumentParser()

    for key, parser in subparsers.items():
        # treat all common args like --repository or --config as if they were
        # required rather than optional, and thus always consume one argument
        # from the given arg list.
        for arg in common_args_parser.add_argument_group("common arguments"):
            if not parser.has_argument(arg.dest):
                parser.add_argument(*arg.option_strings, dest=arg.dest, required=True)

    # conclude the common args group and add any remaining arguments to it, and
    # then initialize the argument parser to hold the freed-up common args
    for arg in common_args_parser.add_argument_group("remaining arguments"):
        if not common_args_parser.has_argument(arg.dest):
            common_args_parser.add_argument(*arg.option_strings, dest=arg.dest)

    for arg in unparsed_arguments:
        try:
            common_args, pid = common_args_parser.parse_known_args([arg])
        except SystemExit:
            remaining_args.append(arg)
        else:
            subparsers_result = subparsers[pid].parse_args(remaining_args)
            parser_results[pid] = subparsers_result
            remaining_args = []

    return parser_results, remaining_args

