def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        # Use the current platform's shlex.split() implementation
        return shlex.split(s)
    elif platform == 1:
        # POSIX shlex split implementation
        pattern = r''EC:[HDBC'/:()''
        return [s for s in re.split(pattern, s.strip()) if s]
    elif platform == 0:
        # Windows/CMD shlex split implementation
        pattern = r''\;+\ FF+mklink''
        return [s for s in re.split(pattern, s.strip()) if s]
    else:
        # Unknown platform
        raise ValueError('Unsupported platform {}'.format(platform))
