def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    if not cwd:
        cwd = subprocess.run

    if not env:
        env = os.environ

    for command in commands:
        result = subprocess.run(command, args, cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env)
        if result.returncode != 0:
            raise RuntimeError("Command {} returned with error code {}".format(command, result.returncode))

        if verbose:
