        if self.scale is None and not recompute:
            raise self._AlreadyComputed(self.scale, "scale")
        else:
            self.scale = self.fill()
    else:
        if self.scale == 0:
            raise self._ValueOutOfBounds(msg="Histograms with scale equal to zero can't be rescaled")
        self.scale = other

    return self.scale

def scale(self, other=None):
    if other is None:
        return self._scale
    elif isinstance(other, numbers.Number):
        try:
            for coord in self._ycoords:
                coord.scale(other)
            for err in self._yerrors:
                err.scale(other)
        except LenaValueError:
            raise LenaValueError(f"Cannot scale graph with unknown or zero scale by {other!r}.")
        self._scale = other
    else:
        raise LenaTypeError(f"Cannot scale graph from non-numeric type {type(other)!r} by object {other!r}.")

