def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*.

    Arguments:
        iface (type): A type that implements the interface.
        candidate (type or object): An object that claims to implement the interface or its class.
        tentative (bool, optional): If True, verify that the candidate satisfies the interface's requirements but do not assert this. Default: False.

    Returns:
        bool: A boolean indicating whether the *candidate* satisfies the interface's requirements.
    """
    try:
        if tentative:
            return isinstance(candidate, iface) or any(issubclass(type(candidate), i) for i in iface.__mro__)
        else:
            assert isinstance(candidate, iface) or any(issubclass(type(candidate), i) for i in iface.__mro__)
            return True
    except AssertionError:
        return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If explicit_mc is given, return it
    if explicit_mc is not None:
        return explicit_mc

    # If no bases, return default metaclass
    if not bases:
        return type

    # If bases has a meta attribute, return it
    if hasattr(bases[0], '__metaclass__'):
        return bases[0].__metaclass__

    # If all bases have the same __metaclass__, return it
    metaclass = getattr(bases[0], '__metaclass__', None)
    for base in bases[1:]:
        if base.__metaclass__ != metaclass:
            return type(getattr(base, '__metaclass__', type))

    # return type if we get here
    return type(metaclass)

