def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): A dictionary of parsed spec files

    Returns:
        dict: A flattened dictionary containing all the key-value pairs from the included files
    """

    # Iterate over the parser dictionary and check for includes
    for key, value in parser_dict.items():
        if isinstance(value, dict) and "include" in value:
            # If the value is a dictionary and contains an "include" key, flatten the dictionary
            include_dict = value["include"]
            for include_key, include_value in include_dict.items():
                if isinstance(include_key, str) and include_key.endswith(".yaml") and include_value:
                    # If the include key is a string and ends with ".yaml" and has a value,
                    # try to load the file and recursively call the function
                    try:
                        with open(include_key, "r") as f:
                            include_dict[include_key] = yaml.safe_load(f)
                            parser_dict.update(_include_groups(include_dict[include_key]))
                    except FileNotFoundError:
                        pass

    return parser_dict

