def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    This method is mainly used to resolve default values for arguments that are not provided by the user, based on the information specified in the spec.
    """

    # Get the values of default arguments from the spec
    from typing import get_type_hints, Union
    from fractions import Fraction
    from decimal import Decimal
    for name, param in self.__signature__.parameters.items():
        if param.default is not param.empty:
            spec_default = param.annotation
            if spec_default is Union:
                spec_default = None
            elif spec_default is float:
                spec_default = 0.0
            elif spec_default is int:
                spec_default = 0
            elif spec_default is bool:
                spec_default = False
            elif spec_default is str:
                spec_default = ""
            elif spec_default is Fraction:
                spec_default = Fraction()
            elif spec_default is Decimal:
                spec_default = Decimal()

            # Override the default value if it is provided in the spec
            argument_value = getattr(self, name)
            if argument_value is not None:
                continue

            setattr(self, name, spec_default)
